 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Repeated square motifs contain a central marker. Connect equal rare
    # markers across the blank lanes, aligned horizontally and vertically.
    step = 7 if h >= 28 else 5
    size = 5 if step == 7 else 4
    rs = list(range(1, h-size+1, step))
    cs = list(range(1, w-size+1, step))
    center = size // 2
    markers = [[grid[r+center][c+center] for c in cs] for r in rs]
    common = {0, 1, 2, 3, 4}
    colors = {x for row in markers for x in row if x not in common}
    for color in colors:
        for i, r in enumerate(rs):
            found = [j for j, v in enumerate(markers[i]) if v == color]
            if len(found) > 1:
                for a, b in zip(found, found[1:]):
                    for x in range(cs[a] + size, cs[b]):
                        for y in range(r + center, min(r + center + (2 if size == 5 else 1), h)):
                            if grid[y][x] == 0:
                                out[y][x] = color
        for j, c in enumerate(cs):
            found = [i for i in range(len(rs)) if markers[i][j] == color]
            if len(found) > 1:
                for a, b in zip(found, found[1:]):
                    for y in range(rs[a] + size, rs[b]):
                        for x in range(c + center, min(c + center + (2 if size == 5 else 1), w)):
                            if grid[y][x] == 0:
                                out[y][x] = color
    return out

